// Без персональних даних: лише назва сценарію, вузол, текст помилки (його рушій уже очищує від credentials).
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $json.error || {};
const w = $json.workflow || {};
const x = $json.execution || {};
let message = String(e.message || 'без опису');
if (message.length > 500) message = message.slice(0, 499) + '…';
const status = x.status === 'timed_out' ? 'перевищено час виконання' : 'помилка';
return {
  chat_id: $json.admin_chat_id,
  parse_mode: 'HTML',
  text: '🚨 <b>Збій сценарію «' + esc(w.name) + '»</b> (' + status + ')\n\n' +
        (e.nodeName ? 'Вузол: ' + esc(e.nodeName) + '\n' : '') +
        esc(message) + '\n\nВиконання: <code>' + esc(x.id) + '</code>',
};
